      "citation": "Liu, C.J.; McKay, G.; Jiang, D.; Tenorio, R.; Cath, J.T.; Amador, C.; Murray, C.C.; Brown, J.B.; Wright, H.B.; Schaefer, C.; et al. Pilot-scale field demonstration of a hybrid nanofiltration and UV-sulfite treatment train for groundwater contaminated by per- and polyfluoroalkyl substances (PFASs). Water Research. 2021, 205, 117677.",
      "comparability": {
        "evidence_locator_ids": [
          "S04-E01",
          "S04-E04",
          "S04-E05",
          "S04-E06",
          "S04-E08"
        ],
        "reason": "Pilot-scale NF\u2013UV-sulfite treatment of AFFF-impacted groundwater with clearly defined batch volume, recovery, reject volume, operating conditions, and PFAS rejection allows comparison to other membrane-based PFAS treatment trains when considering similar matrices (groundwater), high-pressure membranes, and concentrate-focused destructive processes.",
        "status": "comparable_with_conditions"
      },
      "doi_or_stable_url": "https://doi.org/10.1016/j.watres.2021.117677",
      "endpoints": [
        {
          "endpoint_type": "separation",
          "evidence_locator_ids": [
            "S04-E01",
            "S04-E08"
          ],
          "interpretation": "Pilot NF achieved high rejection of individual PFASs (generally 92\u201398%) in AFFF-impacted groundwater at 90% permeate recovery, concentrating PFAS mass into the \u224810% reject stream and reducing the volume requiring downstream treatment.",
          "reported_term": "PFAS rejection by NF"
        },
        {
          "endpoint_type": "destruction",
          "evidence_locator_ids": [
            "S04-E01",
            "S04-E04"
          ],
          "interpretation": "PFASs concentrated in the NF reject were subjected to UV-sulfite treatment at pH 11.2, and the authors report that PFAS destruction was accomplished; rates for individual PFASs were consistent with trends from prior small-scale studies. The reported term is destruction, but the evidence is based on PFAS parent-compound loss rather than full mineralization.",
          "reported_term": "PFAS destruction by UV-sulfite"
        },
        {
          "endpoint_type": "removal",
          "evidence_locator_ids": [
            "S04-E01",
            "S04-E04",
            "S04-E08"
          ],
          "interpretation": "The hybrid NF plus UV-sulfite train separates PFASs from bulk groundwater into a small-volume NF reject and then reduces PFAS mass in that reject; all water streams are polished by GAC before discharge to manage any residual PFASs.",
          "reported_term": "Overall PFAS removal in treatment train"
        }
      ],
      "limitations": [
        {
          "basis": "author_reported",
          "evidence_locator_ids": [
            "S04-E01"
          ],
          "statement": "High-pressure membranes are not frequently used for PFAS treatment due to challenges associated with managing the PFAS-rich concentrate stream."
        },
        {
          "basis": "author_reported",
          "evidence_locator_ids": [
            "S04-E01"
          ],
          "statement": "pH adjustment of the NF reject to 11.2 for UV-sulfite treatment, followed by neutralization, may create additional operating challenges and costs."
        },
        {
          "basis": "design_inferred",
          "evidence_locator_ids": [
            "S04-E04",
            "S04-E05",
            "S04-E08"
          ],
          "statement": "Field trial results are specific to AFFF-impacted groundwater at a single site and a specific NF270-based pilot configuration, which may limit direct generalization to other waters or membranes."
        },
        {
          "basis": "author_reported",
          "evidence_locator_ids": [
            "S04-E08",
            "S04-E05"
          ],
          "statement": "Temporary decreases in PFAS rejection occurred when cation exchange pretreatment was not replaced promptly, allowing Ca2+ and Mg2+ breakthrough and illustrating the sensitivity of NF performance to pretreatment efficacy."
        }
      ],
